1442	+    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
1443	+    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
1444	+    {
1445	+        var digitsStart = 0;
1446	+        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
1447	+        {
1448	+            digitsStart++;
1449	+        }
1450	+
1451	+        var digitsEnd = digitsStart;
1452	+        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
1453	+        {
1454	+            digitsEnd++;
1455	+        }
1456	+
1457	+        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
1458	+            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
1459	+        {
1460	+            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
1461	+        }
1462	+
1463	+        var rowLabel = sitzplatz[..digitsStart];
1464	+        return (rowLabel, columnNumber);
1465	+    }
1466	+}
