2150	+/// <summary>
2151	+/// Erstellt für jede Testklasse eine eigene, eindeutig benannte Testdatenbank auf dem echten
2152	+/// SQL Server aus ConnectionStrings__Default (Consistency Convention „Test-Engine für
2153	+/// Nebenläufigkeit“ — kein EF-Core-InMemory-Provider, da gefilterte Unique-Constraints sonst
2154	+/// nicht durchgesetzt würden). Schema wird über die echten EF-Core-Migrations aufgebaut, damit
2155	+/// die Migration selbst mitgetestet wird.
2156	+/// </summary>
2157	+public sealed class SqlServerTestDatabase : IAsyncLifetime
2158	+{
2159	+    private readonly string _connectionString;
2160	+
2161	+    public SqlServerTestDatabase()
2162	+    {
2163	+        var baseConnectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
2164	+            ?? throw new InvalidOperationException("ConnectionStrings__Default ist für die Tests nicht gesetzt.");
2165	+
2166	+        var builder = new SqlConnectionStringBuilder(baseConnectionString)
2167	+        {
2168	+            InitialCatalog = $"seed_a_test_{Guid.NewGuid():N}",
2169	+        };
2170	+        _connectionString = builder.ConnectionString;
2171	+    }
2172	+
2173	+    public AppDbContext CreateContext()
2174	+    {
2175	+        var options = new DbContextOptionsBuilder<AppDbContext>()
2176	+            .UseSqlServer(_connectionString)
2177	+            .Options;
2178	+        return new AppDbContext(options);
2179	+    }
2180	+
2181	+    public async ValueTask InitializeAsync()
2182	+    {
2183	+        await using var db = CreateContext();
2184	+        await db.Database.MigrateAsync();
2185	+    }
2186	+
2187	+    public async ValueTask DisposeAsync()
2188	+    {
2189	+        await using var db = CreateContext();
2190	+        await db.Database.EnsureDeletedAsync();
2191	+    }
2192	+}
