1591	+/// <summary>Bewacht AD-5: Domain/ bleibt frei von EF-Core-/ASP.NET-Core-Typen und -Attributen.</summary>
1592	+public class DomainDependencyDirectionTests
1593	+{
1594	+    private static readonly Type[] DomainTypes =
1595	+    [
1596	+        typeof(Venue), typeof(Room), typeof(Event), typeof(PriceCategory), typeof(Booking), typeof(BookingPosition),
1597	+    ];
1598	+
1599	+    [Fact]
1600	+    public void Domain_Typen_haben_keine_Properties_mit_EF_Core_oder_AspNetCore_Typen()
1601	+    {
1602	+        foreach (var type in DomainTypes)
1603	+        {
1604	+            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
1605	+            {
1606	+                Assert.False(IsForbiddenNamespace(property.PropertyType.Namespace),
1607	+                    $"{type.Name}.{property.Name} referenziert einen unerlaubten Typ aus '{property.PropertyType.Namespace}'.");
1608	+            }
1609	+        }
1610	+    }
1611	+
1612	+    [Fact]
1613	+    public void Domain_Typen_tragen_keine_Datenannotationen()
1614	+    {
1615	+        foreach (var type in DomainTypes)
1616	+        {
1617	+            foreach (var property in type.GetProperties(BindingFlags.Public | BindingFlags.Instance))
1618	+            {
1619	+                foreach (var attribute in property.GetCustomAttributes())
1620	+                {
1621	+                    Assert.False(IsForbiddenNamespace(attribute.GetType().Namespace),
1622	+                        $"{type.Name}.{property.Name} trägt ein Attribut aus '{attribute.GetType().Namespace}'.");
1623	+                }
1624	+            }
1625	+        }
1626	+    }
1627	+
1628	+    private static bool IsForbiddenNamespace(string? ns) =>
1629	+        ns is not null && (ns.StartsWith("Microsoft.AspNetCore", StringComparison.Ordinal)
