43	    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
44	    {
45	        var spielstaetten = data.Spielstaetten
46	            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'spielstaetten'-Feld.");
47	        var veranstaltungen = data.Veranstaltungen
48	            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'veranstaltungen'-Feld.");
49	
50	        var venueIds = new HashSet<string>();
51	        foreach (var venueDto in spielstaetten)
52	        {
53	            if (!venueIds.Add(venueDto.Id))
54	            {
55	                throw new InvalidOperationException($"Spielstätte '{venueDto.Id}' ist im Anfangsdatenbestand mehrfach vorhanden.");
56	            }
57	        }
58	
59	        foreach (var eventDto in veranstaltungen)
60	        {
61	            if (!venueIds.Contains(eventDto.SpielstaetteId))
62	            {
63	                throw new InvalidOperationException(
64	                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{eventDto.SpielstaetteId}'.");
65	            }
66	        }
67	
68	        var venues = new List<Venue>();
69	
70	        foreach (var venueDto in spielstaetten)
71	        {
72	            var venue = new Venue { Name = venueDto.Name };
73	            var roomsById = new Dictionary<string, Room>();
74	
75	            var raeume = venueDto.Raeume
76	                ?? throw new InvalidOperationException($"Spielstätte '{venueDto.Id}' enthält kein 'raeume'-Feld.");
77	
78	            foreach (var roomDto in raeume)
79	            {
80	                var aisleColumns = roomDto.Gang?.Spalten ?? new List<int>();
81	                foreach (var column in aisleColumns)
82	                {
83	                    if (column < 1 || column > roomDto.Spalten)
84	                    {
85	                        throw new InvalidOperationException(
86	                            $"Raum '{roomDto.Id}': Gang-Spalte '{column}' liegt außerhalb des Sitzplans (1..{roomDto.Spalten}).");
87	                    }
88	                }
89	
90	                if (!roomsById.TryAdd(roomDto.Id, new Room
91	                {
92	                    Name = roomDto.Name,
93	                    RowLabels = roomDto.Reihen ?? new List<string>(),
94	                    ColumnCount = roomDto.Spalten,
95	                    AisleColumns = aisleColumns,
96	                }))
97	                {
98	                    throw new InvalidOperationException(
99	                        $"Spielstätte '{venueDto.Id}' enthält den Raum '{roomDto.Id}' mehrfach.");
100	                }
101	
102	                venue.Rooms.Add(roomsById[roomDto.Id]);
103	            }
104	
105	            foreach (var eventDto in veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
106	            {
107	                if (!roomsById.TryGetValue(eventDto.RaumId, out var room))
108	                {
109	                    throw new InvalidOperationException(
110	                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{eventDto.RaumId}' in Spielstätte '{venueDto.Id}'.");
111	                }
112	
113	                var @event = new Event
114	                {
115	                    Titel = eventDto.Titel,
116	                    Beschreibung = eventDto.Beschreibung,
117	                    Zeitpunkt = eventDto.Zeitpunkt,
118	                    DauerMinuten = eventDto.DauerMinuten,
119	                    Altersfreigabe = eventDto.Altersfreigabe,
120	                };
121	
122	                var preiskategorien = eventDto.Preiskategorien
123	                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'preiskategorien'-Feld.");
124	
125	                foreach (var priceCategoryDto in preiskategorien)
126	                {
127	                    if (priceCategoryDto.Preis < 0)
128	                    {
129	                        throw new InvalidOperationException(
130	                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen negativen Preis ({priceCategoryDto.Preis}).");
131	                    }
132	
133	                    @event.PriceCategories.Add(new PriceCategory
134	                    {
135	                        Name = priceCategoryDto.Name,
136	                        Preis = priceCategoryDto.Preis,
137	                    });
138	                }
139	
140	                var belegteSitzplaetze = eventDto.BelegteSitzplaetze
141	                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'belegteSitzplaetze'-Feld.");
142	
143	                var gesehen = new HashSet<(string RowLabel, int ColumnNumber)>();
144	                foreach (var sitzplatz in belegteSitzplaetze)
145	                {
146	                    if (sitzplatz is null)
147	                    {
148	                        throw new FormatException(
149	                            $"Veranstaltung '{eventDto.Id}' enthält einen leeren (null) Eintrag in 'belegteSitzplaetze'.");
150	                    }
151	
152	                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
153	
154	                    if (!gesehen.Add((rowLabel, columnNumber)))
155	                    {
156	                        throw new InvalidOperationException(
157	                            $"Veranstaltung '{eventDto.Id}' listet den Sitzplatz '{sitzplatz}' mehrfach in 'belegteSitzplaetze'.");
158	                    }
159	
160	                    if (!room.RowLabels.Contains(rowLabel))
161	                    {
162	                        throw new InvalidOperationException(
163	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' referenziert die unbekannte Reihe '{rowLabel}' in Raum '{eventDto.RaumId}'.");
164	                    }
165	
166	                    if (columnNumber < 1 || columnNumber > room.ColumnCount)
167	                    {
168	                        throw new InvalidOperationException(
169	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt außerhalb der Spaltenzahl (1..{room.ColumnCount}) von Raum '{eventDto.RaumId}'.");
170	                    }
171	
172	                    if (room.AisleColumns.Contains(columnNumber))
173	                    {
174	                        throw new InvalidOperationException(
175	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt auf einer Gang-Spalte von Raum '{eventDto.RaumId}'.");
176	                    }
177	
178	                    @event.BookingPositions.Add(new BookingPosition
179	                    {
180	                        RowLabel = rowLabel,
181	                        ColumnNumber = columnNumber,
182	                        BookingId = null,
183	                        PriceCategoryId = null,
184	                        CancelledAtUtc = null,
185	                    });
186	                }
187	
188	                room.Events.Add(@event);
189	            }
