197	
198	    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
199	    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
200	    {
201	        var digitsStart = 0;
202	        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
203	        {
204	            digitsStart++;
205	        }
206	
207	        var digitsEnd = digitsStart;
208	        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
209	        {
210	            digitsEnd++;
211	        }
212	
213	        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
214	            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
215	        {
216	            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
217	        }
218	
219	        var rowLabel = sitzplatz[..digitsStart];
220	        return (rowLabel, columnNumber);
221	    }
222	}
